 const states={scheduled:'Scheduled',unestimated:'Needs estimate',paused:'Paused',blocked:'Blocked',completed:'Completed',empty:'No work items'},conflicts=itemPopup.expanded?detail.conflicts:detail.conflicts.slice(0,2),issues=itemPopup.expanded?detail.issues:detail.issues.slice(0,2);
