function storyRoles(){return [...data.roles].sort((a,b)=>a.name.localeCompare(b.name))}
function storyTeamFields(source=null){const existing=source?storyRoleIds(source,data):new Set();return `<fieldset class="story-teams"><legend>Teams & estimates</legend><p class="panel-sub">Choose roles now. Assignees and estimates can be added later.</p><div class="story-team-list">${storyRoles().map((role,index)=>`<section class="story-team-row" data-story-team="${index}" ${existing.has(role.id)?'data-story-existing':''}><label class="checkline story-team-heading"><input type="checkbox" name="phase_${index}" data-story-include aria-label="Include ${esc(role.name)}" ${existing.has(role.id)?'checked disabled':''}><strong>${esc(role.name)}</strong>${existing.has(role.id)?'<span class="soft-tag">Added</span>':''}</label><div class="story-team-fields"><div class="field"><label for="phase_owner_${index}" class="visually-hidden">${esc(role.name)} assignee</label><select id="phase_owner_${index}" name="phase_owner_${index}" disabled>${personOptions('',true,null,role.id)}</select></div><div class="field"><label for="phase_days_${index}" class="visually-hidden">${esc(role.name)} estimate (days)</label><input type="number" id="phase_days_${index}" name="phase_days_${index}" min="0.5" max="3650" step="0.5" placeholder="Days" disabled></div></div></section>`).join('')||'<p class="panel-sub">Add roles in Team & roles to estimate this story.</p>'}</div><div class="story-team-summary" role="status" data-story-summary>No roles selected</div><label class="checkline"><input type="checkbox" name="sequential"> ${source?'Link new roles after this work item':'Link selected teams as dependencies in the order shown'}</label><small class="panel-sub">Work days, not calendar days. Dependencies are optional.</small></fieldset>`}
function syncStoryTeams(){
 const form=$('#modalForm');if(!form||!['feature','story'].includes(view.modal?.type))return;
 let count=0,total=0,pending=0,invalid=false;
 $$('[data-story-team]').forEach(row=>{
  if(row.hasAttribute('data-story-existing'))return;
  const selected=row.querySelector('[data-story-include]').checked;
  row.classList.toggle('selected',selected);
  row.querySelectorAll('select,input[type="number"]').forEach(field=>field.disabled=!selected);
  if(!selected)return;count++;
  const estimate=row.querySelector('input[type="number"]'),value=Number(estimate.value);
  if(!estimate.value.trim())pending++;else if(!estimate.validity.valid||!Number.isFinite(value))invalid=true;else total+=value;
 });
 const summary=$('[data-story-summary]');if(summary)summary.textContent=count?`${count} work item${count===1?'':'s'} · ${invalid?'Use estimates in 0.5-day steps':pending?`${num(total,2)}d known effort · ${pending} to estimate later`:String(Math.round(total*1000000)/1000000)+'d total effort'}`:view.modal.sourceTaskId?'Choose new roles to add':view.modal.type==='feature'?'No roles selected · add a story name or create an empty feature':'Create one sub-item · estimate later';
 const submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=invalid||Boolean(view.modal.sourceTaskId&&!count);
}
