function cycleCheck(taskId,dependencies){const visit=(id,seen=new Set())=>{if(id===taskId)return true;if(seen.has(id))return false;seen.add(id);let t=getTask(id);return(t?.dependsOn||[]).some(next=>visit(next,seen))};return dependencies.some(id=>visit(id))}
